type IconChevronProps = {
  className?: string;
  color?: "default" | "white";
  shape?: "right" | "up";
};

function IconChevron({ className, color = "white", shape = "right" }: IconChevronProps) {
  const isUpAndDefault = shape === "up" && color === "default";
  const isUpAndWhite = shape === "up" && color === "white";
  return (
    <div className={className || "relative size-[24px]"} id={isUpAndWhite ? "node-1135_297" : isUpAndDefault ? "node-1135_293" : "node-1135_289"}>
      <img alt="" className="absolute block inset-0 max-w-none size-full" src={isUpAndWhite ? imgShapeUpColorWhite : isUpAndDefault ? imgShapeUpColorDefault : imgShapeRightColorWhite} />
    </div>
  );
}

